<template><section class="content-card"><div class="page-title"><div><p class="eyebrow">АДМИНИСТРИРОВАНИЕ</p><h1>Мастера</h1><p>Настройте специалистов, рабочее время и доступные услуги.</p></div><Button label="Добавить мастера" icon="pi pi-plus" @click="showForm=!showForm"/></div><form v-if="showForm" class="master-form" @submit.prevent="create"><InputText v-model="form.fio" placeholder="ФИО мастера"/><InputText v-model="form.specialnost" placeholder="Специальность"/><InputText v-model="form.telefon" placeholder="Телефон"/><label>Начало<input class="native-input" type="time" v-model="form.nachalo_raboty"></label><label>Конец<input class="native-input" type="time" v-model="form.konec_raboty"></label><MultiSelect v-model="form.usluga_ids" :options="services" optionLabel="nazvanie" optionValue="id" placeholder="Услуги мастера" display="chip"/><Button type="submit" label="Сохранить"/></form><DataTable :value="items" stripedRows><Column field="fio" header="ФИО"/><Column field="specialnost" header="Специальность"/><Column header="График"><template #body="{data}">Пн–Пт, {{short(data.nachalo_raboty)}}–{{short(data.konec_raboty)}}</template></Column><Column header="Услуги"><template #body="{data}"><span v-for="s in data.uslugi" :key="s.id" class="service-chip">{{s.nazvanie}}</span></template></Column><Column><template #body="{data}"><Button icon="pi pi-trash" severity="danger" text aria-label="Удалить" @click="remove(data)"/></template></Column><template #empty><div class="empty-state">Добавьте первого мастера</div></template></DataTable></section></template>
<script>import DataTable from'primevue/datatable';import Column from'primevue/column';import Button from'primevue/button';import InputText from'primevue/inputtext';import MultiSelect from'primevue/multiselect';import{useDataStore}from'@/stores/dataStore';export default{components:{DataTable,Column,Button,InputText,MultiSelect},data:()=>({store:useDataStore(),items:[],services:[],showForm:false,form:{fio:'',specialnost:'',telefon:'',nachalo_raboty:'09:00',konec_raboty:'18:00',usluga_ids:[]}}),async mounted(){await this.load();await this.store.get_usluga(0,100);this.services=this.store.usluga},methods:{async load(){await this.store.get_kosmetolog();this.items=this.store.kosmetolog},async create(){try{await this.store.create_master(this.form);this.showForm=false;this.form={fio:'',specialnost:'',telefon:'',nachalo_raboty:'09:00',konec_raboty:'18:00',usluga_ids:[]};await this.load();this.$toast.add({severity:'success',summary:'Мастер добавлен',life:2500})}catch(e){this.$toast.add({severity:'error',summary:'Ошибка',detail:e.response?.data?.message||'Проверьте поля',life:3500})}},async remove(data){try{await this.store.delete_master(data.id);await this.load()}catch(e){this.$toast.add({severity:'error',summary:'Нельзя удалить',detail:e.response?.data?.message,life:3500})}},short(v){return v?.slice(0,5)}}}</script>
